s=s.replace('onPick: () => void }> }) { return <label className="typeahead"><span>{label}</span><div className="search-box"><Search size={17} /><input value={value} placeholder={placeholder} onChange={(e) => { setValue(e.target.value); }} /><button type="button" onClick={onClear}><X size={15} /></button></div>', 'onPick: () => void }>; disabled?: boolean }) { return <label className={`typeahead ${disabled ? "typeahead-disabled" : ""}`}><span>{label}</span><div className="search-box"><Search size={17} /><input disabled={disabled} value={value} placeholder={placeholder} onChange={(e) => { setValue(e.target.value); }} /><button type="button" disabled={disabled} onClick={onClear}><X size={15} /></button></div>')
